"Форма листа помогает раскрыть замысел": "Жапырақтың пішіні ойды ашуға көмектеседі",
"Форма предмета — это его строение.": "Заттың пішіні — оның құрылымы.",
"Форма — наружный вид предмета. Конструкция — его строение: чайник или ваза состоят из геометрических тел, например шара, конуса и цилиндра.": "Пішін — заттың сыртқы көрінісі. Конструкция — оның құрылымы: шәйнек немесе ваза геометриялық денелерден, мысалы, шардан, конустан және цилиндрден тұрады.",
"Форма, пластика и объём — выразительные средства скульптуры.": "Пішін, пластика және көлем — мүсіннің көркемдегіш құралдары.",
"Форму мы видим со стороны": "Пішінді біз сырттай көреміз",
"Функциональное изделие должно быть полезным и удобным.": "Функционалдық бұйым пайдалы әрі ыңғайлы болуы керек.",
"Холодная гамма": "Суық гамма",
"Холодные цвета напоминают воду и лёд": "Суық түстер су мен мұзды еске түсіреді",
"Холодные цвета напоминают лёд и ночь": "Суық түстер мұз бен түнді еске түсіреді",
"Холодные цвета передают ночную тишину": "Суық түстер түнгі тыныштықты жеткізеді",
"Хорошее изделие не только красивое, но и удобное. Дизайнер продумывает, для чего вещь нужна.": "Жақсы бұйым тек әдемі ғана емес, ыңғайлы да болады. Дизайнер заттың не үшін керек екенін ойластырады.",
"Хороший дизайн соединяет красоту и пользу": "Жақсы дизайн сұлулық пен пайданы біріктіреді",
"Художественное конструирование может начинаться с наброска на бумаге.": "Көркем конструкциялау қағаздағы нобайдан басталуы мүмкін.",
"Цветовое решение": "Түстік шешім",
"Чеканка относится к работе с металлом": "Бедерлеп соғу металмен жұмыс істеуге жатады",
"Чеканка по металлу — это техника лепки из глины.": "Металға бедерлеп соғу — бұл саздан мүсіндеу техникасы.",
"Человек — портрет, природа — пейзаж, предметы — натюрморт": "Адам — портрет, табиғат — пейзаж, заттар — натюрморт",
"Чем дальше предмет, тем бледнее, светлее и размытее он выглядит. Этот приём называется воздушной перспективой.": "Зат неғұрлым алыс болса, соғұрлым ол бозғылт, ашық және бұлыңғыр көрінеді. Бұл тәсіл ауа перспективасы деп аталады.",
"Чем дальше предмет, тем он ярче и контрастнее.": "Зат неғұрлым алыс болса, соғұрлым ол жарқын әрі контрастырақ.",
"Чем рисуют мелкие детали, например птиц в небе?": "Ұсақ бөлшектерді, мысалы, көктегі құстарды немен салады?",
"Чем украшают одежду в этой работе?": "Бұл жұмыста киімді немен безендіреді?",
"Что делает мастер, чтобы подготовить идею украшенного чайника?": "Безендірілген шәйнектің идеясын дайындау үшін шебер не істейді?",
"Что делают на первом шаге решения дизайнерской задачи?": "Дизайн есебін шешудің бірінші қадамында не істейді?",
