"Что называют опорами моста?": "Көпір тіректері деп нені атайды?",
"Что называют рельефом?": "Бедер деп нені атайды?",
"Что нужно приготовить для росписи чайника?": "Шәйнекті бояумен өрнектеу үшін нені дайындау керек?",
"Что нужно, чтобы мыть кисть при работе красками?": "Бояумен жұмыс істегенде қылқаламды жуу үшін не қажет?",
