"Ножницы передают кольцами вперёд и режут без спешки. Готовую работу покажи классу и расскажи, как делал.": "Қайшыны сақиналарымен алға қаратып береді және асықпай қияды. Дайын жұмысты сыныпқа көрсетіп, қалай жасағаныңды айтып бер.",
