"Нормана Фостера": "Норман Фостердің",
"О чём напоминает образ шанырака?": "Шаңырақ бейнесі нені еске салады?",
"Обе стороны узора должны совпадать": "Өрнектің екі жағы да сәйкес келуі керек",
"Образ в других искусствах": "Басқа өнер түрлеріндегі бейне",
"Образ есть во многих искусствах": "Бейне көптеген өнер түрлерінде бар",
"Образ создаётся средствами выразительности": "Бейне көркемдегіш құралдар арқылы жасалады",
"Образ шанырака говорит о единстве людей, живущих в Казахстане.": "Шаңырақ бейнесі Қазақстанда тұратын адамдардың бірлігін білдіреді.",
"Образ шанырака — символ общего дома": "Шаңырақ бейнесі — ортақ үйдің символы",
"Образ — это то, как художник видит предмет или явление и показывает это в работе.": "Бейне — суретші затты немесе құбылысты қалай көретінін көрсетіп, оны жұмысында бейнелеуі.",
"Образы можно создавать не только в рисунке, но и в танце, театре и кино.": "Бейнелерді суретте ғана емес, биде, театрда және киноде де жасауға болады.",
"Объектив — часть фотоаппарата.": "Объектив — фотоаппараттың бір бөлігі.",
