"Окна у дома бывают только круглые.": "Үйдің терезелері тек дөңгелек болады.",
"Он в центре герба": "Ол елтаңбаның ортасында",
"Он вдавлен внутрь, как отпечаток": "Ол із сияқты ішке қарай басылған",
"Он есть и в бумажной модели": "Ол қағаз макетте де бар",
"Он иллюстрировал книги": "Ол кітаптарға иллюстрация салды",
"Он напоминает огромный шатёр": "Ол алып шатырды еске салады",
"Он невысокий рельеф": "Ол — аласа бедер",
"Он основоположник профессионального искусства Казахстана": "Ол — Қазақстандағы кәсіби өнердің негізін қалаушы",
"Он рисует графическими материалами": "Ол графикалық материалдармен сурет салады",
