"Слепи из пластилина или глины плоскую заготовку толщиной около 1 см. Вдави в неё камешки или мелкие игрушки, чтобы получился контррельеф, либо вылепи барельеф. Потом спрячь артефакты в коробку с песком и осторожно раскопай их кисточкой. Стеку держи острием вниз и работай аккуратно; пластилин и глину не пробуй на вкус и вымой руки после работы.": "Пластилиннен немесе саздан қалыңдығы шамамен 1 см жалпақ дайындама жаса. Оған тастарды немесе ұсақ ойыншықтарды баса сал, сонда контрбедер шығады, немесе барельеф мүсінде. Содан кейін артефактілерді құмы бар қорапқа жасырып, оларды қылқаламмен абайлап қаз. Стекті ұшын төмен қаратып ұста да, ұқыпты жұмыс істе; пластилин мен сазды татып көрме және жұмыстан кейін қолыңды жу.",
