"Сначала замысел, потом эскиз": "Алдымен жоспар, содан кейін эскиз",
"Сначала идея, потом эскиз в выбранной технике, затем украшение яркими цветами и деталями. В конце проводят презентацию и оценивают работу.": "Алдымен идея, содан кейін таңдалған техникадағы эскиз, одан кейін жарқын түстермен және бөлшектермен әшекейлеу. Соңында таныстырылым өткізіп, жұмысты бағалайды.",
