"Кабанбай жил в XVIII веке и защищал земли от джунгарских отрядов": "Қабанбай XVIII ғасырда өмір сүрген және жерді жоңғар қосындарынан қорғаған",
"Каждый слой аккуратно поднимают вверх": "Әр қабатты мұқият жоғары көтереді",
