"Казахстанские художники развивали линогравюру и литографию.": "Қазақстандық суретшілер линогравюра мен литографияны дамытты.",
"Как безопасно пользоваться острым карандашом?": "Өткір қарындашты қалай қауіпсіз пайдалануға болады?",
"Как безопасно работать с карандашами и мелками?": "Қарындаштармен және борлармен қалай қауіпсіз жұмыс істеуге болады?",
"Как в скульптуре можно показать контраст?": "Мүсінде контрастты қалай көрсетуге болады?",
