"Как вырезать цветок из квадрата бумаги по способу сложения?": "Қағаздың шаршысынан бүктеу тәсілімен гүлді қалай қиюға болады?",
"Как закладка с редким растением помогает природе?": "Сирек өсімдік бейнеленген бетбелгі табиғатқа қалай көмектеседі?",
"Как лучше передать в скульптуре движение птицы?": "Мүсінде құстың қозғалысын қалай жақсырақ жеткізуге болады?",
"Как люди передавали сказки и легенды в древние времена?": "Ертеде адамдар ертегілер мен аңыздарды қалай жеткізген?",
