"Как называют портрет или скульптуру человека до груди?": "Адамның кеудесіне дейінгі портретін немесе мүсінін қалай атайды?",
"Как называют художника, который рисует картинки для книг?": "Кітаптарға суреттер салатын суретшіні қалай атайды?",
