"Какое дерево, предок многих сортов яблонь, растёт в горах Казахстана и занесено в Красную книгу?": "Алма ағаштарының көптеген сорттарының арғы тегі, Қазақстан тауларында өсетін және Қызыл кітапқа енген ағаш қайсы?",
"Какое это валяние?": "Бұл қандай киіз басу?",
"Какой инструмент подходит для рисунка, а не для печатной формы?": "Баспа қалыбына емес, сурет салуға қандай құрал жарайды?",
